import bpy,json
from pathlib import Path
from mathutils import Vector
c=bpy.data.collections['Shipyard_COMBINED_Craft']
report={'file':bpy.data.filepath,'editable_objects':len(c.objects),'export_objects':len(bpy.data.collections['Shipyard_COMBINED_Export'].objects),'materials':{},'new_component_groups':{},'bounds':None}
co=[o.matrix_world@Vector(p) for o in c.objects for p in o.bound_box]
report['bounds']={'lo':[min(p[i] for p in co) for i in range(3)],'hi':[max(p[i] for p in co) for i in range(3)]}
for o in c.objects:
 if o.name.startswith('Steel '):
  group=' '.join(o.name.split()[:3]);report['new_component_groups'][group]=report['new_component_groups'].get(group,0)+1
 for m in o.data.materials:
  if not m or m.name in report['materials']:continue
  report['materials'][m.name]={'users':m.users,'textures':[{'name':n.image.name,'size':list(n.image.size),'file':n.image.filepath,'packed':bool(n.image.packed_file)} for n in m.node_tree.nodes if n.type=='TEX_IMAGE' and n.image]}
p=Path(bpy.data.filepath).parent.parent/'captures'/'shipyard_steel_20261111'/'source_audit.json';p.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
print('AUDIT_SAVED',str(p))
